class DRESModel:
    def __init__(self, model, **kwargs):
        self.model = model
        self.use_sbert_model = isinstance(model, SentenceTransformer)

    def encode_queries(self, queries: list[str], **kwargs) -> np.ndarray:
        if self.use_sbert_model:
            return self.model.encode(
                queries,
                **kwargs,
            )
        else:
            return self.model.encode(queries, prompt_type=PromptType.query, **kwargs)

    def encode_corpus(
        self, corpus: list[dict[str, str]] | dict[str, list], **kwargs
    ) -> np.ndarray:
        if isinstance(corpus, dict):
            sentences = [
                (
                    (corpus["title"][i] + " " + corpus["text"][i]).strip()
                    if "title" in corpus
                    else corpus["text"][i].strip()
                )
                for i in range(len(corpus["text"]))
            ]
        else:
            sentences = [
                (
                    (doc["title"] + " " + doc["text"]).strip()
                    if "title" in doc
                    else doc["text"].strip()
                )
                for doc in corpus
            ]
        if self.use_sbert_model:
            return self.model.encode(
                sentences,
                **kwargs,
            )
        else:
            return self.model.encode(sentences, prompt_type=PromptType.passage, **kwargs)


